///$tab Main
SET ThousandSep=' ';
SET DecimalSep=',';
SET MoneyThousandSep=' ';
SET MoneyDecimalSep='.';
SET MoneyFormat='# ##0.00 CHF;-# ##0.00 CHF';
SET TimeFormat='hh:mm:ss';
SET DateFormat='DD.MM.YYYY';
SET TimestampFormat='DD.MM.YYYY hh:mm:ss[.fff]';
SET FirstWeekDay=0;
SET BrokenWeeks=0;
SET ReferenceDay=4;
SET FirstMonthOfYear=1;
SET CollationLocale='fr-CH';
SET CreateSearchIndexOnReload=1;
SET MonthNames='janv.;févr.;mars;avr.;mai;juin;juil.;août;sept.;oct.;nov.;déc.';
SET LongMonthNames='janvier;février;mars;avril;mai;juin;juillet;août;septembre;octobre;novembre;décembre';
SET DayNames='lun.;mar.;mer.;jeu.;ven.;sam.;dim.';
SET LongDayNames='lundi;mardi;mercredi;jeudi;vendredi;samedi;dimanche';
SET NumericalAbbreviation='3:k;6:M;9:G;12:T;15:P;18:E;21:Z;24:Y;-3:m;-6:μ;-9:n;-12:p;-15:f;-18:a;-21:z;-24:y';

///$tab variables
// //01.06.2023 Thomas AUGUET gestion de l'historique des données

let vNumWeekDay=num(weekday(today()));
// let vNumWeekDay=6;//pour tester 30 min

let vNumWeekdayFullReloadSurLesChamps=6;//dimanche full reload des champs et année pour l'app de recherche de données

let vChargement='R3';
// let vChargement='S4';

$(Include=lib://QVD_SAP/config.txt);

/*
    0 pour lundi
    1 pour mardi
    2 pour mercredi
    3 pour jeudi
    4 pour vendredi
    5 pour samedi
    6 pour dimanche
*/

if vNumWeekDay=vNumWeekdayFullReloadSurLesChamps then //si on est sur le jour du full reload (pour la partie DEV - fouille de données dans les tables SAP)
    trace 'On s''occupe de l''historique';
    let vAnneeDeb='1990';
    if '$(vChargement)'='R3' then
      let vDossier='lib://QVD_SAP/DFIN/fullReload';
      let vDossierSave='DataModelFullReload';
    elseif '$(vChargement)'='S4' then
      let vDossier='lib://QVD_SAP/DFIN_S4/fullReload';
      let vDossierSave='DataModelFullReload';
    end if;
Else 
    trace 'On s''occupe seulement des 3 dernières années';
    let vAnneeDeb=Year(Today())-3;
    if '$(vChargement)'='R3' then
      let vDossier='lib://QVD_SAP/DFIN';
      let vDossierSave='DataModel';
    elseif '$(vChargement)'='S4' then
      let vDossier='lib://QVD_SAP/DFIN_S4';
      let vDossierSave='DataModel';
    end if;
end if;

let vAnneeFin=Year(Today())+1;//pour le calendrier
///$tab Mapping
// MapEKKN_45_46:
// MApping LOAD distinct
// 	EKKN.EBELN as KEY,
//     EKKN.FKBER//domaine fonctionnel
// FROM [$(vDossier)/EKKN.qvd]
// (qvd);

MapEKKN:
MApping LOAD distinct
	EKKN.EBELN&'-'&right(EKKN.EBELP,5)&'-'&EKKN.ZEKKN as KEY_EKKN_COOI_PORD,//Correction_code du 23.07.2024 par DavidC, remplacement de KBLNR par EBELN
    EKKN.FKBER
FROM [$(vDossier)/EKKN.qvd]
(qvd);

// MapEKKN_2:
// MApping LOAD distinct
// 	EKKN.EBELN&'-'&EKKN.ZEKKN as KEY_EKKN_COOI_PORD,//Correction_code du 23.07.2024 par DavidC, remplacement de KBLNR par EBELN
//     EKKN.FKBER
// FROM [$(vDossier)/EKKN.qvd]
// (qvd);

MapFMIOI_tmp:
LOAD
	FMIOI.REFBN&'-'&FMIOI.RFPOS as KEY_FMIOI_COOI_FMRESorZCMC,
    FMIOI.FAREA as DF,
    FMIOI.ZHLDT as DateClé
FROM [$(vDossier)/FMIOI.qvd]
// (qvd) WHERE left(FMIOI.WRTTP,2)<>'51';//Correction_code du 23.07.2024 par DavidC
(qvd)
WHERE wildmatch(left(FMIOI.WRTTP,2),'65','81','82')>0
AND len(trim(replace(FMIOI.FAREA,' 	','')))>0;//NEW correction du 06.08.2024 sur demande de DavidC --- Correction_code du 23.07.2024 par DavidC
left join(MapFMIOI_tmp)
LOAD
	FMIOI.REFBN&'-'&FMIOI.RFPOS as KEY_FMIOI_COOI_FMRESorZCMC,
    MAX(FMIOI.ZHLDT) as DateCléMax
FROM [$(vDossier)/FMIOI.qvd]
// (qvd) WHERE left(FMIOI.WRTTP,2)<>'51';//Correction_code du 23.07.2024 par DavidC
(qvd) 
WHERE wildmatch(left(FMIOI.WRTTP,2),'65','81','82')>0
AND len(trim(replace(FMIOI.FAREA,' 	','')))>0
GROUP BY (FMIOI.REFBN&'-'&FMIOI.RFPOS);

MapFMIOI:
Mapping LOAD 
KEY_FMIOI_COOI_FMRESorZCMC,DF
Resident MapFMIOI_tmp WHERE DateClé=DateCléMax;
drop table MapFMIOI_tmp;

MapOTP_OTP1:
Mapping Load Distinct
    PRPS.OBJNR as [OTP],
	MAXSTRING([PRPS.FKSTL]) as [Centre de coûts OTP 1]
FROM [$(vDossier)/PRPS.qvd](qvd)
WHERE left(PRPS.OBJNR,2)='PR'
  group by PRPS.OBJNR
;

MapOTP_OTP2:
Mapping Load Distinct
    PRPS.OBJNR as [OTP],
    MAXSTRING([PRPS.AKSTL]) as [Centre de coûts OTP 2]
FROM [$(vDossier)/PRPS.qvd](qvd)
WHERE left(PRPS.OBJNR,2)='PR'
  group by PRPS.OBJNR
;

// qualify *;
MapEKKN:
NoConcatenate
LOAD distinct
	EKKN.EBELN&'-'&right(EKKN.EBELP,5)&'-'&EKKN.ZEKKN as KEY_EKKN_COOI_PORD,//Correction_code du 23.07.2024 par DavidC, remplacement de KBLNR par EBELN
    EKKN.FKBER as value
FROM [$(vDossier)/EKKN.qvd]
(qvd);
// MapEKKN_2:
// NoConcatenate
// LOAD distinct
// 	EKKN.EBELN&'-'&EKKN.ZEKKN as KEY_EKKN_COOI_PORD,//Correction_code du 23.07.2024 par DavidC, remplacement de KBLNR par EBELN
//     EKKN.FKBER as value
// FROM [$(vDossier)/EKKN.qvd]
// (qvd);
// MapEKKN_45_46:
// LOAD distinct
// 	EKKN.EBELN as KEY,
//     EKKN.FKBER as value
// ;
// LOAD *
// FROM [$(vDossier)/EKKN.qvd]
// (qvd);
MapFMIOI:
NoConcatenate
LOAD
	FMIOI.REFBN&'-'&FMIOI.RFPOS as KEY_FMIOI_COOI_FMRESorZCMC,
    FMIOI.FAREA
FROM [$(vDossier)/FMIOI.qvd]
// (qvd) WHERE left(FMIOI.WRTTP,2)<>'51';//Correction_code du 23.07.2024 par DavidC
(qvd) WHERE wildmatch(left(FMIOI.WRTTP,2),'65','81','82')>0
AND len(trim(replace(FMIOI.FAREA,' 	','')))>0;//NEW correction du 06.08.2024 sur demande de DavidC --- Correction_code du 23.07.2024 par DavidC

// COOI_tmp:
// LOAD *
// FROM [$(vDossier)/COOI.qvd]
// (qvd);

// unqualify *;
///$tab Engagement R/3 & S/4
Engagement:
LOAD 
	*,
    ApplyMap('MapOTP_OTP1',OTP) as [Centre de coûts OTP 1],
    ApplyMap('MapOTP_OTP2',OTP) as [Centre de coûts OTP 2]
;
LOAD
	Rowno() as %keyEngagement,
	COOI.OBJNR as REF_LIGNE,
	COOI.BUDAT as [Date comptable],
	if(left([COOI.OBJNR],2)='OR',1,0) as [Est un Ordre Interne],
	if(left([COOI.OBJNR],2)='KS','Centre de coûts',if(left([COOI.OBJNR],2)='PR','OTP','Ordre interne')) as [Type d'analyse],
    [COOI.GJAHR]&'-'&right([COOI.PERIO],2) as AnnéeMois,
    [COOI.SAKTO] 	as [Num Nature comptable],
    [COOI.WKGBTR] 	as Engagement,
    [COOI.REFBN] 	as [Numéro de pièce],
    COOI.RFPOS 		as [Numéro de poste de la pièce de référence],
    COOI.RFKNT 		as [Numéro d'imputation de la pièce de référence],
//     COOI.REFBN&'-'&COOI.RFPOS as [Numéro de pièce, Rattachement par ligne],//pour la fusion
    COOI.REFBN&'-'&COOI.RFPOS&'-'&[COOI.WKGBTR]&'-'&COOI.RFKNT 
    				as [Numéro de pièce, Rattachement par ligne],//update le 25.01.2024 pour gérer les ORCM négatifs -- update le 15.02.2024 en ajoutant COOI.RFKNT pour éviter la ségrégation prévue des OI CM
    [COOI.REFBN]&'-'&[COOI.RFPOS]&'-'&COOI.RFKNT //24.10.2024 : TA sur demande de David on ajoute COOI.RFKNT pour être suffisament précis dans la clé SAP CO
    				as [N° pièce, Ligne d'écriture (LgE)],//utilisé comme clé SAP CO
    COOI.GJAHR&'-'&COOI.REFBN 
    				as [Année-Numéro de pièce],
/*17.07.2024 : David C : 
A mon avis, tu vires le premier mapping, tu modifies le deuxième mapping en rajoutant ZEKKN, ce qui fait que la clé nouvelle utilise 
les champs: KBLNR, VBELP, ZEKKN (N° d'imputation), tu gardes le 3ème mapping.
Je profite pour te donner une version actualisée de Finding_022.xlsx (seulement au niveau de l'onglet Analyse 1), qui devient Finding_022.b. 
C'est ton doc. de procédure qui est à l'origine de cette actualisation.
*/
//     if(wildmatch(COOI.REFBN,'45*','46*')>0,
//     	ApplyMap('MapEKKN_45_46',COOI.REFBN,'NC MapEKKN_45_46'),
        if(COOI.RFTYP = 'PORD',
          ApplyMap('MapEKKN',COOI.REFBN&'-'&COOI.RFPOS&'-'&right(COOI.RFKNT,2),'NC MapEKKN'),
//           	ApplyMap('MapEKKN_2',COOI.REFBN&'-'&right(COOI.RFKNT,2), 'NC MapEKKN et MapEKKN_2')),
          if((COOI.RFTYP = 'FMRES' OR COOI.RFTYP = 'ZCMC') AND [COOI.WRTTP]<>'22',
              ApplyMap('MapFMIOI',COOI.REFBN&'-'&COOI.RFPOS, 'NC MapFMIOI'),
              'NC AUTRE'
          )
        )
    //)
    														as [ID Domaine Fonctionnel Engagement],
    COOI.WRTTP 												as [Type de valeur],
    if(match([COOI.WRTTP], '2A','2B'),COOI.REFBN,null()) 	as [Numéro de réservation de Fonds],
    if([COOI.WRTTP]='22',COOI.REFBN,null()) 				as [Numéro de commande],
    //text(RIGHT([COOI.RFPOS],3)) 							as [Poste de la Commande], //exemple 00010
    [COOI.LIFNR] 											as [ID Fournisseur Engagement],//ici on a le lien direct vers le fournisseur
    COOI.SGTXT 												as [Libellé],
    COOI.RFTYP 												as [Type de pièce d'origine - engagement],
    COOI.KOKRS 												as [Périmètre analytique],
    'Engagement' 											as Classe,
    if(match([COOI.WRTTP], '22','24','60'),0,if(match([COOI.WRTTP], '2A','2B'),1,2)) as [Est un engagement avec réservé],  //0 : sans réservé ; 1 : avec réservé ; 2 : autre
    //spécifique centre de coûts
    if(left([COOI.OBJNR],2)='KS',replace([COOI.OBJNR],left([COOI.OBJNR],6),''),null()) as [Num Centre de coûts],
    //spécifique OTP
// 	text(if(left([COOI.OBJNR],2)='PR',[COOI.OBJNR],null())) as [OTP], 
    if(left([COOI.OBJNR],2)='PR',[COOI.OBJNR],null()) as [OTP],//29.02.2024 on retire le text qui peut provoquer un probleme sur la jointure CC responsable et demandeur
    //spécifique CM
	if(left([COOI.OBJNR],2)='OR',[COOI.OBJNR],null()) as [OR],
	if(left([COOI.OBJNR],2)='OR',mid([COOI.OBJNR],3),null()) as [Ordre interne],
//     if(left([COOI.OBJNR],2)='OR',COOI.GJAHR&'-'&COOI.REFBN,null()) as [Année-Numéro de pièce OR]
    if(left([COOI.OBJNR],2)='OR',COOI.REFBN,null()) as [Année-Numéro de pièce OR]
FROM [$(vDossier)/COOI.qvd]
(qvd)
WHERE (left([COOI.OBJNR],2)='KS' OR left([COOI.OBJNR],2)='PR' OR left([COOI.OBJNR],2)='OR')
  AND (COOI.GJAHR)>='$(vAnneeDeb)'
//   AND left(COOI.OBJNR,4)<>'ORCM'//Règle énoncée par David le 17.04.2023 car ces écritures s'annulent //supprimé sur demande de David le 25.01.2024 car il nous manque justement les OI de type CM
;

//Récupération des CM
left join
LOAD distinct
    COOI.REFBN as [Numéro de pièce],
    MAXSTRING(replace(COOI.OBJNR,'OR','')) as [Contrat Engagement]
FROM [$(vDossier)/COOI.qvd](qvd)
WHERE (left(COOI.OBJNR,4)='ORCM')
  AND (COOI.GJAHR)>='$(vAnneeDeb)'
  group by COOI.REFBN
;

//récupération des CC pour les ordres internes
left join
load distinct 
	COOI.REFBN as [Année-Numéro de pièce OR], 
    MAXSTRING(COOI.OBJNR) as [Centre de coûts Ordre interne Engagement]
FROM [$(vDossier)/COOI.qvd](qvd)
WHERE left(COOI.OBJNR,2)='KS'
  group by COOI.REFBN
;

// Pierre
// left join
// LOAD distinct
//     EKKN.EBELN 			as [Numéro de commande],
//     EKKN.KBLNR 			as [Numéro de réservation de Fonds de la Commande],
//    	EKKN.KBLPOS 	    as [Poste de la Commande]
//     //,
//     //text(EKKN.PAOBJNR) 	as [OTP]
// FROM [$(vDossier)/EKKN.qvd]
// (qvd);


// Fix du 16.03.2023 pour retirer les doublons générés plus haut
left join
LOAD distinct
    EKKN.EBELN&'-'&EKKN.EBELP 	as [N° pièce, Ligne d'écriture (LgE)],//15.05.2023 Thomas AUGUET update clé //04.07.2023 Update de la clé
    EKKN.KBLNR 					as [Numéro de réservation de Fonds de la Commande],
    EKKN.KBLPOS 				as [Poste de la Commande]
//     MAXSTRING(EKKN.KBLNR) 			as [Numéro de réservation de Fonds de la Commande], // 15.05.2023 plus besoin d'aggrég car on a la bonne clé
//     MAXSTRING(EKKN.KBLPOS) 			as [Poste de la Commande]
    //,
    //text(EKKN.PAOBJNR) 	as [OTP]
FROM [$(vDossier)/EKKN.qvd]
(qvd)
//   group by EKKN.EBELN,EKKN.EBELP
;

Qualify *;
V1_Engagement:
LOAD * RESIDENT Engagement;
Unqualify *;

///$tab //début fusion

///$tab Engagement fusion  - Si on a un CC 
EngagementFusionCC: //Centre de coûts
LOAD
    REF_LIGNE&'-CC-Engagement-'&AnnéeMois as REF_LIGNE,
    [Type de valeur],
    [Date comptable],
	[Numéro de pièce, Rattachement par ligne],
	[Numéro de pièce, Rattachement par ligne] as KeyCC,
    "Numéro de commande",
//     "Année-Numéro de pièce OR",
    [Numéro de pièce],
    [Numéro de poste de la pièce de référence],
    [Numéro d'imputation de la pièce de référence],
    "Type d'analyse",
//     "Est un Ordre Interne",
    AnnéeMois,
    "Num Nature comptable",
    Engagement,
    "N° pièce, Ligne d'écriture (LgE)",
    "Année-Numéro de pièce",
    "ID Domaine Fonctionnel Engagement",
    "Numéro de réservation de Fonds",
    "ID Fournisseur Engagement",
    Libellé,
    "Type de pièce d'origine - engagement",
    "Périmètre analytique",
    Classe,
    "Est un engagement avec réservé",
    "Num Centre de coûts",
//     OTP,
//     "OR",
//     "Ordre interne",
    "Contrat Engagement",
//     "Centre de coûts Ordre interne Engagement",
    "Numéro de réservation de Fonds de la Commande",
    "Poste de la Commande",
    1 as AUneEcritureCentreDeCouts,
    1 as fieldEngagementFusionCC
Resident Engagement WHERE [Type d'analyse]='Centre de coûts';

left join 
LOAD distinct
    [Numéro de pièce, Rattachement par ligne],
    [Année-Numéro de pièce OR],
    [Est un Ordre Interne],
    [Ordre interne],
    [OR],
    [Centre de coûts Ordre interne Engagement],
	1 as AUneEcritureOrdreInterne
Resident Engagement WHERE [Type d'analyse]='Ordre interne';

left join
LOAD distinct
    [Numéro de pièce, Rattachement par ligne],
    [OTP],
//     [Centre de coûts OTP],
//     [Centre de coûts responsable],
//     [Centre de coûts demandeur],
    [Centre de coûts OTP 1],
    [Centre de coûts OTP 2],
    1 as AUneEcritureOTP
Resident Engagement WHERE [Type d'analyse]='OTP';
///$tab Engagement fusion  - Si on a un OI
EngagementFusionOI: //OI
LOAD distinct
    REF_LIGNE&'-OI-Engagement-'&AnnéeMois as REF_LIGNE,
    [Type de valeur],
    [Date comptable],
    "Est un engagement avec réservé",
    Engagement,
    [Numéro de pièce, Rattachement par ligne] as KeyOI,
    [Numéro de pièce, Rattachement par ligne],
    [Numéro de pièce],
    [Numéro de poste de la pièce de référence],
    [Numéro d'imputation de la pièce de référence],
    AnnéeMois,
    "Num Nature comptable",
    Libellé,
    Classe,
    "N° pièce, Ligne d'écriture (LgE)",
    [ID Domaine Fonctionnel Engagement],
    [Année-Numéro de pièce OR],
    [Est un Ordre Interne],
    [Ordre interne],
    [OR],
    [Centre de coûts Ordre interne Engagement],
    "Type de pièce d'origine - engagement",
    "ID Fournisseur Engagement",
	1 as AUneEcritureOrdreInterne,
    1 as fieldEngagementFusionOI
Resident Engagement WHERE [Type d'analyse]='Ordre interne' 
AND NOT Exists(KeyCC,[Numéro de pièce, Rattachement par ligne]);

left join
LOAD distinct
    [Numéro de pièce, Rattachement par ligne],
    [OTP],
//     [Centre de coûts OTP],
//     [Centre de coûts responsable],
//     [Centre de coûts demandeur],
    [Centre de coûts OTP 1],
    [Centre de coûts OTP 2],
    1 as AUneEcritureOTP
Resident Engagement WHERE [Type d'analyse]='OTP';
///$tab Engagement fusion  - Si on a un OTP
EngagementFusionOTP: //OTP
LOAD distinct
    REF_LIGNE&'-OTP-Engagement-'&AnnéeMois as REF_LIGNE,
    [Type de valeur],
    [Date comptable],
    "Est un engagement avec réservé",
    Engagement,
    [Numéro de pièce, Rattachement par ligne] as KeyOTP,
    [Numéro de pièce, Rattachement par ligne],
    [ID Domaine Fonctionnel Engagement],
    [Numéro de pièce],
    [Numéro de poste de la pièce de référence],
    [Numéro d'imputation de la pièce de référence],
    "N° pièce, Ligne d'écriture (LgE)",
    AnnéeMois,
    "Num Nature comptable",
    Libellé,
    Classe,
    [OTP],
    "Type de pièce d'origine - engagement",
//     [Centre de coûts OTP],
//     [Centre de coûts responsable],
//     [Centre de coûts demandeur],
    [Centre de coûts OTP 1],
    [Centre de coûts OTP 2],
    "ID Fournisseur Engagement",
    1 as AUneEcritureOTP,
    1 as fieldEngagementFusionOTP
Resident Engagement WHERE [Type d'analyse]='OTP' 
AND NOT Exists(KeyCC,[Numéro de pièce, Rattachement par ligne])
AND NOT Exists(KeyOI,[Numéro de pièce, Rattachement par ligne]);
///$tab CONCATENATE
Engagementfinal:
LOAD *
, 1 as Engagementfinal 
Resident EngagementFusionCC;

if FieldNumber(fieldEngagementFusionOI,'EngagementFusionOI')>= 0 then
  CONCATENATE(Engagementfinal)
  LOAD * Resident EngagementFusionOI;
  drop table EngagementFusionOI;
end if;

if FieldNumber(fieldEngagementFusionOTP,'EngagementFusionOTP')>= 0 then
  CONCATENATE(Engagementfinal)
  LOAD * Resident EngagementFusionOTP;
  drop table EngagementFusionOTP;
end if;

Engagementfinalfinal:
LOAD *
,1 as EngagementFinalfinal
,if(AUneEcritureCentreDeCouts=1,1,0) as AUneEcritureCentreDeCouts_Final
,if(AUneEcritureOrdreInterne=1,1,0) as AUneEcritureOrdreInterne_Final
,if(AUneEcritureOTP=1,1,0) as AUneEcritureOTP_Final
Resident Engagementfinal;

drop field EngagementFinalfinal;
drop field Engagementfinal;

drop field AUneEcritureCentreDeCouts;
rename field AUneEcritureCentreDeCouts_Final to AUneEcritureCentreDeCouts;
drop field AUneEcritureOrdreInterne;
rename field AUneEcritureOrdreInterne_Final to AUneEcritureOrdreInterne;
drop field AUneEcritureOTP;
rename field AUneEcritureOTP_Final to AUneEcritureOTP;

drop table Engagementfinal;

drop table Engagement;
drop table EngagementFusionCC;

rename table Engagementfinalfinal to Engagement;


///$tab Selection_OI_OTP_CC_engagement
//19.04.2023 (Thomas AUGUET) : ajout de ce filtre de sélection pour facilement prendre une écriture qui contient un OI ou OTP ou CC
Selection_OI_OTP_CC_engagement:
LOAD REF_LIGNE,
'OTP' as [Présence d'une écriture OTP/OI/CC]
RESIDENT Engagement
WHERE AUneEcritureOTP=1
;
CONCATENATE(Selection_OI_OTP_CC_engagement)
LOAD REF_LIGNE,
'OI' as [Présence d'une écriture OTP/OI/CC]
RESIDENT Engagement
WHERE AUneEcritureOrdreInterne=1
;
CONCATENATE(Selection_OI_OTP_CC_engagement)
LOAD REF_LIGNE,
'CC' as [Présence d'une écriture OTP/OI/CC]
RESIDENT Engagement
WHERE AUneEcritureCentreDeCouts=1
;
///$tab Store
STORE * FROM [Engagement] INTO [$(vDossier)/$(vDossierSave)_TEST_v1.5_FUSION/Engagement.qvd];
STORE * FROM [Selection_OI_OTP_CC_engagement] INTO [$(vDossier)/$(vDossierSave)_TEST_v1.5_FUSION/Selection_OI_OTP_CC_engagement.qvd];

